package com.bn5212.mimic.demo.controller;
import com.bn5212.mimic.demo.dto.PredictRequest;import com.bn5212.mimic.demo.service.DemoService;import com.bn5212.mimic.model.ModelService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") public class DemoController {private final DemoService service;private final ModelService models;public DemoController(DemoService service,ModelService models){this.service=service;this.models=models;}@GetMapping("/health") Map<String,Object> health(){return Map.of("status","ok","artifacts_ready",models.ready(),"mode","preliminary-course-demo");}@GetMapping("/tasks") Map<String,Object> tasks(){return Map.of("tasks",service.tasks(),"disclaimer","Educational demo only; outputs are not diagnoses or clinical recommendations.");}@GetMapping("/summary") Object summary(){return service.summary();}@GetMapping("/results") Map<String,Object> results(){Map<String,Object> s=service.summary();return Map.of("tasks",s.get("tasks"),"robustness",s.get("robustness"),"status","preliminary_demo");}@PostMapping("/demo/predict") Map<String,Object> predict(@Valid @RequestBody PredictRequest req){return service.predict(req);}}
